sql_query:
SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Follow-up duration for primary endpoint(s) in months | Overall", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Follow-up duration for primary endpoint(s) in months | Overall" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Follow-up duration for primary endpoint(s) in months | Overall", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Atezolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_followup_maturity(source_value) AS "maturity"
FROM base;
